import { View, Text, SectionList, StyleSheet } from "react-native";
import { registerRootComponent } from "expo";

const SECTIONS = [
  { title: "Гар утас", data: ["iPhone 15", "Samsung S24"] },
  { title: "Компьютер", data: ["Ноутбук Pro", "Хулгана"] },
];

function App() {
  return (
    <SectionList
      style={styles.screen}
      sections={SECTIONS}
      keyExtractor={(item, i) => item + i}
      renderSectionHeader={({ section }) => (
        <View testID="section-header" style={styles.header}>
          <Text style={styles.headerText}>{section.title}</Text>
        </View>
      )}
      renderItem={({ item }) => (
        <View testID="product" style={styles.row}>
          <Text>{item}</Text>
        </View>
      )}
    />
  );
}

const styles = StyleSheet.create({
  screen: { flex: 1, backgroundColor: "#f8fafc" },
  // энд бичнэ үү: header загварт backgroundColor нэмж гарчгийг тодотго
  header: { padding: 12 },
  headerText: { fontSize: 16, fontWeight: "bold", color: "#3730a3" },
  row: { padding: 16, backgroundColor: "#fff" },
});

registerRootComponent(App);

